package dev.zomboid.turretpower;
import java.util.*;import dev.zomboid.turretpower.Checks.*;import dev.zomboid.survival.MachineEntity;import com.entropy.tacz_turrets.turret.TurretEntity;
public class TimingChecks{static int count;static void ok(boolean b,String why){count++;if(!b)throw new AssertionError(why);}public static void main(String[]a){W w=new W();TurretEntity turret=new TurretEntity(w);T target=new T(w);turret.target=target;P pos=new P(0,0,0);MachineEntity g=new MachineEntity();w.machines.put(pos,g);w.blocks.put(pos,new S("doomsday_decoration:generator"));MachineEntity.GENERATORS.put(w,Set.of(pos));int start=g.energy.stored;
 for(int t=0;t<16;t++){w.time=t;ok(!Link.allowed(turret),"first round must wait 16 ticks");Fire early=new Fire(turret);Link.fire(early);ok(early.canceled&&g.energy.stored==start,"early attempts consume no energy");}w.time=16;Fire first=new Fire(turret);Link.fire(first);ok(!first.canceled&&g.energy.stored==start-100,"first shot exactly at tick 16");
 for(int shot=1;shot<=6;shot++){for(int d=1;d<10;d++){w.time=16+(shot-1)*10+d;ok(!Link.allowed(turret),"ten tick interval between every round");}w.time=16+shot*10;Fire f=new Fire(turret);Link.fire(f);ok(!f.canceled&&g.energy.stored==start-100*(shot+1),"round every ten ticks, no accelerated burst");}
 w.time++;turret.visible=false;Link.tick(turret);ok(!Link.allowed(turret),"wall immediately blocks fire");turret.visible=true;long reacquired=w.time;for(int i=0;i<16;i++){w.time=reacquired+i;ok(!Link.allowed(turret),"reacquisition waits again");}w.time=reacquired+16;ok(Link.allowed(turret),"reacquired after sixteen ticks");
 turret.target=new T(w);long swap=w.time;ok(!Link.allowed(turret),"different target waits");w.time=swap+16;ok(Link.allowed(turret),"new target ready");g.energy.stored=0;Link.tick(turret);ok(!Link.allowed(turret),"no generator energy no fire");g.energy.stored=10000;ok(!Link.allowed(turret),"restoring power begins acquisition");w.time+=16;ok(Link.allowed(turret),"power reacquired with full delay");turret.distance=400.01;ok(!Link.allowed(turret),"outside twenty blocks blocked");turret.distance=400;ok(!Link.allowed(turret),"twenty inclusive reacquires");w.time+=16;ok(Link.allowed(turret),"twenty block boundary valid");w.client=true;ok(!Link.allowed(turret),"client cannot authorize fire");System.out.println("TURRET_TIMING_CHECKS="+count);}}
